const LoadingOverlayFC: FC<{
	show: boolean;
}> = ({ show }) => {
	if (show) {
		return (
			<div className="loading-overlay">
				<KolSpin
					_label="loading"
					_show={show}
					_variant="cycle"
					style={{
						backgroundColor: 'transparent',
					}}
				/>
			</div>
		);
	} else {
		return null;
	}
