import type { FC } from 'react';
import React, { useCallback, useRef, useState } from 'react';

import { KolButton, KolInputRange, KolSkeleton } from '@public-ui/react-v19';
import { SampleDescription } from '../components/SampleDescription';

interface EventLogEntry {
	timestamp: string;
	count: number;
	id: number;
}

export const Skeleton: FC = () => {
	const skeletonRef = useRef<HTMLKolSkeletonElement>(null);
	const rangeRef = useRef<HTMLKolInputRangeElement>(null);
	const initialCount = 3;

	const durationFormatter = new Intl.NumberFormat('de-DE', { style: 'unit', unit: 'millisecond', maximumFractionDigits: 1 });
	const timeFormatter = new Intl.DateTimeFormat('de-DE', { hour: '2-digit', minute: '2-digit', second: '2-digit' });

	const [count, setCount] = useState<number>(initialCount);
	const [eventLog, setEventLog] = useState<EventLogEntry[]>([]);
	const [lastEventTime, setLastEventTime] = useState<string>('');
	const [eventCount, setEventCount] = useState<number>(0);
	const [skeletonCount, setSkeletonCount] = useState<number>(20);

	// Render benchmark state
	const [generation, setGeneration] = useState<number>(0);
	const [renderDuration, setRenderDuration] = useState<number | null>(null);
	const [isMeasuring, setIsMeasuring] = useState<boolean>(false);

	// Refs for stable values in closures (no stale closure issues)
	const renderStartTimeRef = useRef<number>(0);
	const expectedCountRef = useRef<number>(20);
	const renderedCountRef = useRef<number>(0);

	const handleLoaded = (event: CustomEvent<number>) => {
		const now = new Date();
		const timestamp = timeFormatter.format(now);
		const newEventCount = eventCount + 1;

		setCount(event.detail);
		setLastEventTime(timestamp);
		setEventCount(newEventCount);

		// Add to event log (keep only last 5 entries)
		setEventLog((prev) => {
			const newEntry: EventLogEntry = {
				timestamp,
				count: event.detail,
				id: newEventCount,
			};
			return [newEntry, ...prev.slice(0, 4)];
		});
	};

	const handleRendered = useCallback(() => {
		renderedCountRef.current += 1;

		if (renderedCountRef.current >= expectedCountRef.current) {
			const duration = performance.now() - renderStartTimeRef.current;
			setRenderDuration(duration);
			setIsMeasuring(false);
		}
	}, []);

	const handleRangeChange = (_event: Event, value: unknown) => {
		const newValue = Number(value);
		setSkeletonCount(newValue);

		// Start benchmark measurement
		renderedCountRef.current = 0;
		expectedCountRef.current = newValue;
		renderStartTimeRef.current = performance.now();
		setRenderDuration(null);
		setIsMeasuring(true);
		setGeneration((prev) => prev + 1);
	};

	const handleRangeBlur = () => {
		// Sicherstellen, dass der interne Wert mit dem State synchronisiert ist
		if (rangeRef.current) {
			rangeRef.current._value = skeletonCount;
		}
	};

	return (
		<>
			<SampleDescription>
				<p>
					KolSkeleton demonstriert Event-Emitter mit automatischem Intervall. Die Komponente emittiert alle 2 Sekunden ein &quot;loaded&quot; Event mit dem
					aktuellen Count-Wert. Über die Buttons kann die Komponente getoggled und fokussiert werden. Der interne ClickButton erhöht bei Klick den Counter.
				</p>
			</SampleDescription>

			<div className="grid md:grid-cols-2 gap-4 mb-4 items-center">
				<div className="grid sm:grid-cols-2 gap-4">
					<KolButton
						_label="Toggle Sichtbarkeit"
						_on={{
							onClick: () => skeletonRef.current?.toggle(),
						}}
						_variant="primary"
					/>
					<KolButton
						_label="Fokus auf Button"
						_on={{
							onClick: () => skeletonRef.current?.focus(),
						}}
						_variant="secondary"
					/>
				</div>
				<div className="grid sm:grid-cols-2 gap-4 items-center">
					<KolInputRange
						ref={rangeRef}
						_label="Anzahl der Skeletons"
						_hideLabel
						_min={1}
						_max={10000}
						_step={25}
						_value={skeletonCount}
						_on={{
							onChange: handleRangeChange,
							onBlur: handleRangeBlur,
						}}
					/>
					<span className="text-sm text-gray-600 whitespace-nowrap">{skeletonCount} Skeletons</span>
				</div>
			</div>

			{/* Render Benchmark */}
			<div className="mb-4 px-3 py-2 border border-gray-300 rounded bg-gray-50 flex items-center gap-4 text-sm">
				<span className="font-semibold">Benchmark:</span>
				<span className={isMeasuring ? 'text-orange-600 font-bold' : renderDuration !== null ? 'text-green-600' : 'text-gray-400'}>
					{isMeasuring ? 'Rendering…' : renderDuration !== null ? 'Fertig' : 'Bereit'}
				</span>
				<span className="font-bold text-blue-600" aria-live="polite">
					{renderDuration !== null ? durationFormatter.format(renderDuration) : '—'}
				</span>
			</div>

			<div className="flex flex-wrap gap-4">
				{Array.from({ length: skeletonCount }, (_, idx) => (
					<KolSkeleton
						key={`skeleton-${generation}-${idx}`}
						_name={`Example ${idx}`}
						onLoaded={idx === 0 ? handleLoaded : undefined}
						onRendered={handleRendered}
						ref={idx === 0 ? skeletonRef : undefined}
					/>
				))}
			</div>

			<div className="mt-6 p-4 border border-gray-300 rounded-lg bg-gray-50">
				<h3 className="text-lg font-semibold mb-3">Event Monitor</h3>
				<div className="grid grid-cols-1 md:grid-cols-2 gap-4">
					<div>
						<p className="font-medium">Aktueller Count-Wert:</p>
						<p className="text-2xl font-bold text-blue-600" aria-live="polite">
							{count}
						</p>
					</div>
					<div>
						<p className="font-medium">Letztes Event:</p>
						<p className="text-lg" aria-live="polite">
							{lastEventTime || 'Noch kein Event empfangen'}
						</p>
					</div>
				</div>
				<div className="mt-4">
					<p className="font-medium mb-2">
						Events empfangen: <span className="font-bold">{eventCount}</span>
					</p>
					{eventLog.length > 0 && (
						<div>
							<p className="font-medium mb-2">Event-Historie (letzte 5):</p>
							<ul className="text-sm space-y-1 max-h-32 overflow-y-auto">
								{eventLog.map((entry) => (
									<li key={entry.id} className="flex justify-between items-center p-2 bg-white rounded border">
										<span>
											#{entry.id}: Count = {entry.count}
										</span>
										<span className="text-gray-500">{entry.timestamp}</span>
									</li>
								))}
							</ul>
						</div>
					)}
				</div>
				<div className="mt-4 p-3 bg-blue-50 rounded">
					<p className="text-sm text-blue-800">
						💡 <strong>Tipp:</strong> Die Komponente emittiert automatisch alle 2 Sekunden ein Event. Klicke auf den &quot;Click Button&quot; in der Komponente,
						um den Count-Wert zu erhöhen.
					</p>
				</div>
			</div>
		</>
	);
};

import type { ToolbarItemsPropType } from '@public-ui/components';
import { KolHeading, KolToolbar } from '@public-ui/react-v19';
import type { FC } from 'react';
import React, { useEffect, useMemo, useState } from 'react';

export const ToolbarItemOrder: FC = () => {
	const [isSubmitting, setIsSubmitting] = useState(false);
	const [isSubmitting2, setIsSubmitting2] = useState(false);

	useEffect(() => {
		let timer: ReturnType<typeof setTimeout>;
		if (isSubmitting) {
			timer = setTimeout(() => {
				setIsSubmitting(false);
			}, 2000);
		}
		return () => clearTimeout(timer);
	}, [isSubmitting]);

	useEffect(() => {
		let timer: ReturnType<typeof setTimeout>;
		if (isSubmitting2) {
			timer = setTimeout(() => {
				setIsSubmitting2(false);
			}, 2000);
		}
		return () => clearTimeout(timer);
	}, [isSubmitting2]);

	const handleSubmit = () => setIsSubmitting(true);
	const handleSubmit2 = () => setIsSubmitting2(true);

	const toolbarItems = useMemo(() => {
		const items: ToolbarItemsPropType = Array.from({ length: 5 }, (_item, index) => ({
			type: 'button',
			_label: `Button ${index + 1}`,
			_on: { onClick: handleSubmit },
			_icons: isSubmitting ? 'fa-solid fa-spinner fa-spin' : void 0,
			_disabled: isSubmitting,
		}));
		return items;
	}, [isSubmitting]);

	const brokenToolbarItems = useMemo(() => {
		const items: ToolbarItemsPropType = Array.from({ length: 5 }, (_item, index) => ({
			type: 'button',
			_label: `Button ${index + 1}`,
			_on: { onClick: handleSubmit2 },
			_disabled: isSubmitting2,
			_icons: isSubmitting2 ? 'fa-solid fa-spinner fa-spin' : void 0,
		}));
		return items;
	}, [isSubmitting2]);

	return (
		<div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
			<KolHeading _label="Disabled Toolbar Buttons Bug (solved)" />

			<KolHeading _label="icon vor disabled" _level={2} />
			<KolToolbar _label="KolToolbar A" _items={toolbarItems} />
			<KolHeading _label="disabled vor icon" _level={2} />
			<p>Klicke auf einen der {brokenToolbarItems.length - 1} ersten Buttons hatte zur Folge, dass die nachfolgenden Buttons kaputt gehen.</p>
			<KolToolbar _label="KolToolbar B" _items={brokenToolbarItems} />
		</div>
	);
};

